     LEFT JOIN {$p}postmeta sm ON sm.post_id=po.ID AND sm.meta_key='_ps_sandelis'
     WHERE po.post_type='product' AND po.post_status IN ('publish','draft')
       AND (sm.meta_id IS NULL OR sm.meta_value='')
