if(!defined('ABSPATH'))return;
add_action('wp_loaded', function(){
  if(($_GET['ps_z708']??'')!=='Z708x') return;
  if(($_GET['k']??'')!=='ps2026') return;
  if(!headers_sent()){ nocache_headers(); header('Content-Type:application/json; charset=utf-8'); }
  @set_time_limit(200);
  global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'Z708','rezimas'=>$_GET['rezimas']??'dry');
  $dabar=current_time('timestamp');

  // ZB publish, kuriu sync > 24 val.
  $eil=$wpdb->get_results(
    "SELECT po.ID, po.post_title,
       (SELECT meta_value FROM {$p}postmeta WHERE post_id=po.ID AND meta_key='_zb_last_sync') sync,
       (SELECT meta_value FROM {$p}postmeta WHERE post_id=po.ID AND meta_key='_stock') stock,
       (SELECT meta_value FROM {$p}postmeta WHERE post_id=po.ID AND meta_key='_zb_supplier_sku') sku
     FROM {$p}posts po
     INNER JOIN {$p}postmeta sm ON sm.post_id=po.ID AND sm.meta_key='_ps_sandelis' AND sm.meta_value='zb'
     WHERE po.post_type='product' AND po.post_status='publish'", ARRAY_A);
  $kand=array();
  foreach($eil as $r){
    if(empty($r['sync'])){ $amz=null; }
    else { $ts=strtotime($r['sync']); $amz=$ts?($dabar-$ts)/3600:null; }
    if($amz===null || $amz>24){
      $kand[]=array('id'=>(int)$r['ID'],'pav'=>mb_substr(html_entity_decode($r['post_title']),0,46),
        'sku'=>$r['sku'],'sync'=>$r['sync']?mb_substr($r['sync'],0,16):null,
        'val'=>$amz===null?null:round($amz),'stock'=>$r['stock']);
    }
  }
  usort($kand,function($a,$b){ return ($b['val']??999999)<=>($a['val']??999999); });
  $o['kandidatu']=count($kand);
  $o['kandidatai']=$kand;
  $o['su_likuciu']=count(array_filter($kand,function($x){ return (int)$x['stock']>0; }));

  if(($_GET['rezimas']??'')==='apply' && $kand){
    if(!class_exists('Petshop_Katalogas') || !method_exists('Petshop_Katalogas','uztikrinti_zurnala')){
      $o['KLAIDA']='nera Petshop_Katalogas'; echo wp_json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
    }
    $r=new ReflectionMethod('Petshop_Katalogas','uztikrinti_zurnala'); $r->setAccessible(true); $r->invoke(null);
    $t=$wpdb->prefix.'ps_av_zurnalas';
    $op='ZB'.gmdate('ymdHis').wp_rand(10,99);
    $now=current_time('mysql'); $uid=get_current_user_id();
    $n=0; $nepavyko=array();
    foreach($kand as $x){
      $res=wp_update_post(array('ID'=>$x['id'],'post_status'=>'draft'), true);
      if(is_wp_error($res)){ $nepavyko[]=$x['id']; continue; }
      $wpdb->insert($t, array('operacija'=>$op,'product_id'=>$x['id'],'laukas'=>'post_status',
        'buvo'=>'publish','tapo'=>'draft','pokytis'=>null,'priezastis'=>'isimta',
        'user_id'=>$uid,'sukurta'=>$now));
      $n++;
    }
    delete_transient('ps_kat_duomenys');
    $o['operacija']=$op; $o['perkelta']=$n; $o['nepavyko']=$nepavyko;
    $o['liko_publish_senu']=(int)$wpdb->get_var(
      "SELECT COUNT(*) FROM {$p}posts po
       INNER JOIN {$p}postmeta sm ON sm.post_id=po.ID AND sm.meta_key='_ps_sandelis' AND sm.meta_value='zb'
       WHERE po.post_type='product' AND po.post_status='publish'
         AND (SELECT meta_value FROM {$p}postmeta WHERE post_id=po.ID AND meta_key='_zb_last_sync') < DATE_SUB(NOW(), INTERVAL 24 HOUR)");
  }
  echo wp_json_encode($o, JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
}, 6);
